        '**הכלל:** הנתון $g\'(x) = f(x)$ אומר שהפונקציה $f$ היא הנגזרת של $g$, ופונקציה עולה בדיוק בתחומים שבהם הנגזרת שלה חיובית; לכן מחפשים את תחומי החיוביות של $f$, ולא את תחומי העלייה שלה.',
        '**הנוסחה:** פונקציה עולה בתחום שבו $g\'(x) > 0$.',
        '**ההצבה:** מציבים את הנתון במקום הנגזרת ומקבלים את אי השוויון $\\dfrac{x - 2}{x + 3} > 0$.',
        'מאפסים את המונה ומקבלים $x = 2$, ומאפסים את המכנה ומקבלים $x = -3$.',
        'טבלת סימנים למנה:\n\n| $x$ | $x < -3$ | $-3 < x < 2$ | $x > 2$ |\n|---|:---:|:---:|:---:|\n| $x - 2$ | $-$ | $-$ | $+$ |\n| $x + 3$ | $-$ | $+$ | $+$ |\n| $f(x)$ | $+$ | $-$ | $+$ |',
        'המנה חיובית בשני התחומים החיצוניים, ולכן $g$ עולה עבור $x < -3$ וגם עבור $x > 2$.',
