    question:
      'נתונה $f(x) = \\dfrac{\\sqrt{x^2 + 4}}{x}$, ונתונה $g(x) = \\dfrac{1}{\\big(f(x)\\big)^2}$. מהו תחום ההגדרה של $g$, ובאילו תחומים היא עולה ובאילו היא יורדת?',
    answers: [
      'התחום $x \\ne 0$; הפונקציה יורדת עבור $x < 0$ ועולה עבור $x > 0$',
      'התחום הוא כל $x$; הפונקציה יורדת עבור $x < 0$ ועולה עבור $x > 0$',
      'התחום $x \\ne 0$; הפונקציה עולה עבור $x < 0$ ויורדת עבור $x > 0$',
      'התחום $x \\ne 0$; הפונקציה עולה בשני התחומים',
    ],
