      'הסימן של הנגזרת התהפך. במונה של נגזרת המנה כותבים $u\'v - uv\'$ בסדר הזה, ומתקבל $8x$ ולא $-8x$; המכנה הוא ריבוע וחיובי תמיד, ולכן הסימן של הנגזרת הוא הסימן של $x$.',
      'ההנחה כאן היא שהמונה $x^2$ גדל תמיד יחד עם $x$. בתחום השלילי זה אינו נכון: עבור $x = -8$ מתקבל $x^2 = 64$, ועבור $x = -1$ מתקבל $x^2 = 1$, ולכן שם הערכים דווקא קטנים.',
