        'תחום ההגדרה של $f$: הביטוי שתחת השורש $x^2 + 4$ חיובי לכל $x$, והמכנה מחייב $x \\ne 0$.',
        'המונה $\\sqrt{x^2 + 4}$ גדול מאפס תמיד, ולכן $f$ אינה מתאפסת, ותחום ההגדרה של $g$ הוא $x \\ne 0$.',
        'מעלים את $f$ בריבוע: $\\big(f(x)\\big)^2 = \\dfrac{x^2 + 4}{x^2}$.',
        'הופכים את השבר ומקבלים $g(x) = \\dfrac{x^2}{x^2 + 4}$, בתחום $x \\ne 0$.',
        '**הנוסחה:** נגזרת של מנה: $\\left(\\dfrac{u}{v}\\right)\' = \\dfrac{u\'v - uv\'}{v^2}$.',
        '**ההצבה:** מציבים $u = x^2$ וגם $v = x^2 + 4$ ומקבלים $g\'(x) = \\dfrac{2x(x^2 + 4) - x^2 \\cdot 2x}{(x^2 + 4)^2}$.',
        'פותחים ומכנסים את המונה: $2x^3 + 8x - 2x^3 = 8x$.\n\nלכן $g\'(x) = \\dfrac{8x}{(x^2 + 4)^2}$.',
