    hint: 'כפלו את שני השברים ובדקו מה מצטמצם. מה משאיר אחריו גורם שנעלם בצמצום?',
    answerLabels: ['x של האסימפטוטה האנכית', 'y של האסימפטוטה האופקית', 'x של הנקודה החסרה', 'y של הנקודה החסרה'],
