      finalAnswer: '$c = 1$, והאסימפטוטה האופקית של $g$ היא $y = -1$',
      explanation:
        'התנאי על מספר האסימפטוטות האנכיות הוא בעצם תנאי על מספר הפגישות של ישר אופקי עם הגרף של $f$, ולכן הוא נפתר מתוך ערכי הקיצון; ואחרי שהפרמטר נקבע, גובה האסימפטוטה האופקית נובע ישירות מכך שהמכנה שואף להפרש קבוע.',
